import{_ as t,o as i,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-8-update-user/report3_spec_en.md","filePath":"feature/admin-management/3-10-8-update-user/report3_spec_en.md"}'),a={name:"feature/admin-management/3-10-8-update-user/report3_spec_en.md"};function o(s,e,l,u,d,c){return i(),n("div",null,[...e[0]||(e[0]=[r("<p><strong>3.10.8 Update User (Administrative Profile &amp; System Role Modification)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) selects &quot;Edit Profile&quot; on a user record from /admin/users or navigates to /admin/users/:id/edit.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Platform Administrator with authority to update user profiles, subscription plans, and system roles.</li><li><strong>Purpose</strong>: Enables Administrators to adjust user account details, assign new system roles, or modify subscription tiers while strictly safeguarding immutable fields.</li><li><strong>Interface</strong>: Edit User Profile Screen (SCR-ADM-08), displaying account profile form, immutable email indicator, role selector, and audit notes.</li><li><strong>Data Processing</strong>: Validate ADMIN, immutable email, system role and audit justification. Update permitted profile fields; keep Agency ownership separate. Store a requested plan change for the next billing cycle with payment required. Do not immediately change quota, issue a paid receipt or recognize revenue.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Edit User Profile Screen (SCR-ADM-08):</p><ul><li>Left/Header: Admin sidebar; Header with breadcrumbs &quot;Users / Edit Profile&quot;, target User ID, and registration date.</li><li>Center: Editable name/phone/bio/avatar, read-only email; ADMIN/USER system role; Agency roles read-only context. Show current plan, requested catalog plan, next-cycle effective date and payment-required notice. Mandatory justification.</li><li>Buttons: Button &quot;Save Changes&quot; (primary button), Button &quot;Cancel / Return&quot;.</li><li>Footer: Security audit compliance note: &quot;Email address is immutable after creation (BR-19). Role changes take effect on subsequent token refresh. All modifications are tracked in audit_logs.&quot;</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, fullName (2–100 chars), role (ADMIN/USER), justification.</li><li><strong>Input optional</strong>: phoneNumber, bio, avatarUrl, requestedPlanId (existing catalog).</li><li><strong>System data</strong>: adminId, immutable email, currentRole, currentPlan, nextBillingAt, pendingPlanChange and payment state, updatedAt.</li><li><strong>Output</strong>: Updated user profile object with HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-19</strong>: Email remains read-only; reject email mutation through the API.</li><li><strong>BR-82</strong>: System roles are ADMIN and USER only. Agency/Workspace membership roles are managed separately. Subscription plan identifiers come from the existing catalog (currently BASIC, PRO, ENTERPRISE), not a second hardcoded catalog.</li><li><strong>BR-83</strong>: Agency/Workspace ownership changes use their own membership flow. This screen cannot remove the last Owner through a system-role edit; editing the sole Owner profile is allowed.</li><li><strong>BR-23</strong>: Sole Agency/Workspace Owners may receive profile edits, strikes, flags and confirmed 30-day account deactivation. Other members retain their existing permissions; Owner-only operations wait until restoration. Do not suspend the whole Agency or transfer ownership automatically. Agency ownership is separate from system role.</li><li><strong>BR-35</strong>: Admin may not demote or alter the system role of a peer Admin; preserve existing self/peer role safeguards.</li><li><strong>BR-60</strong>: Admin plan change is scheduled for the next billing cycle and still requires customer payment under the existing subscription flow. Current entitlement remains until the cycle boundary. Unpaid change grants no paid entitlement; change action alone creates no revenue or paid invoice.</li><li><strong>BR-16</strong>: Audit profile diffs, role changes, requested plan, effective date and justification separately from actual payment events.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing ADMIN → MSG39; target not found → MSG38; missing fields/justification → MSG02.</li><li>Email mutation, unsupported system role or unknown catalog plan → reject.</li><li>Peer-admin role alteration or Agency ownership mutation through this form → reject.</li><li>Valid sole Owner profile edit → allowed; successful update → MSG26.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Load user profile, separate Agency roles, current plan and next billing date.</li><li>Admin edits permitted profile fields/system role or selects a next-cycle plan and enters justification.</li><li>Validate immutability, role safeguards and catalog values.</li><li>Save profile changes and pending plan change; do not alter current-cycle entitlement.</li><li>Audit changes and show current versus pending plan with effective date and payment requirement.</li><li>Existing subscription billing applies the paid change at the next cycle only after required payment succeeds.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Missing user → MSG38; missing ADMIN → MSG39.</li><li>3.a1: Missing justification or protected field/role mutation → reject without partial update.</li><li>6.a1: Payment fails at renewal → use existing subscription failure policy; no free entitlement or false revenue.</li><li>6.a2: No determinable next billing cycle → route through existing subscription enrollment; do not invent an immediate free upgrade.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Allowed profile fields are updated; email and Agency ownership remain unchanged by this form.</li><li>Pending plan change records next-cycle date and payment requirement; current quota remains until effective change.</li><li>Audit captures changes; revenue updates only on actual financial events.</li></ul>",14)])])}const m=t(a,[["render",o]]);export{g as __pageData,m as default};
